use strict;
use warnings;
use File::Temp qw(tempfile);
use PDL;
use PDL::IO::Protobuf qw(
    rprotobuf wprotobuf from_protobuf to_protobuf pdl_type_for_proto_type
);

# Minimal Protobuf-compatible message class for a self-contained demo.
# In production, use a class generated by the Protobuf distribution.
{
    package DemoProtoVector;
    sub new {
        my ($class, %args) = @_;
        return bless \%args, $class;
    }
    sub id {
        my ($self, $val) = @_;
        $self->{id} = $val if @_ > 1;
        return $self->{id};
    }
    sub values {
        my ($self, $val) = @_;
        $self->{values} = $val if @_ > 1;
        return $self->{values};
    }
    sub serialize {
        my ($self) = @_;
        return pack('d*', @{ $self->{values} || [] });
    }
    sub parse {
        my ($class, $bytes) = @_;
        my @vals = unpack('d*', $bytes);
        return $class->new(values => \@vals);
    }
}

# 1. Serialize a PDL ndarray to a binary .pb file
my $weights = double([1.5, 2.5, 3.5, 4.5]);
my ($fh, $pb_path) = tempfile('pdl_pb_XXXXXX', SUFFIX => '.pb', UNLINK => 1);
close $fh;

wprotobuf($weights, $pb_path, 'DemoProtoVector', 'values');

# 2. Read back from disk and reshape to a 2x2 matrix
my $pdl_type = pdl_type_for_proto_type('double');
print 'Proto double maps to PDL type: ', $pdl_type, "\n";

my $matrix = rprotobuf(
    $pb_path,
    'DemoProtoVector',
    'values',
    proto_type => 'double',
    dims       => [2, 2],
);
print 'Restored 2x2 matrix: ', $matrix, "\n";

# 3. Convert in-memory Protobuf messages without disk I/O
my $out_msg = to_protobuf(
    $matrix * 2.0,
    'DemoProtoVector',
    'values',
    extra_fields => { id => 'scaled-v1' },
);
my $scaled = from_protobuf(
    $out_msg,
    'values',
    proto_type => 'double',
    dims       => [2, 2],
);
print 'In-memory scaled (id=', $out_msg->id, '): ', $scaled, "\n";
